Use customer_behaviour;

Select * from customer_behaviour_data limit 10;
# Q1- What is the total revenue generated by male vs female customers?
Select gender , sum(purchase_amount) As revenue
from customer_behaviour_data 
group by gender;

# Q2- Which customers used a discount but still spent more than the average purchase amount ? 
Select customer_id , purchase_amount
From customer_behaviour_data 
where discount_applied = 'Yes' and purchase_amount > (Select avg(purchase_amount) from customer_behaviour_data);

# Q3- Which are the top 5 products with the highest average review rating?
Select item_purchased , avg(review_rating) As Average_rating
from customer_behaviour_data 
group by item_purchased	
order by Average_rating Desc
limit 5;

# Q4- compare the average purchase amount between standard and Express shipping.
Select shipping_type , Round(avg(purchase_amount),2) as Average_purchase_amount
from customer_behaviour_data
where shipping_type in ('Standard','Express')
group by shipping_type ;

# Q5- Do subscribe customer spend more? Compare average spend n total revenue between subscriber n non subscriber.
Select subscription_status ,Count(customer_id) as Total_customer , Avg(purchase_amount) As Average_Revenue , Sum(purchase_amount) As Total_Revenue 
from customer_behaviour_data 
group by subscription_status 
order by Total_Revenue Desc, Average_Revenue Desc;

# Q6-Which 5 products have the highest percentage of purchase with discount applied?
Select item_purchased , Round(sum(
Case 
When discount_applied = 'Yes' then 1 Else 0
End )* 100 / Count(*),2) As Discount_percentage 
from customer_behaviour_data
group by item_purchased 
order by Discount_percentage Desc
limit 5;

# Q7- Segment customer into New, Returning and loyal based on their no. of previous purchase and show the count of each segment
Select 
  Case
     When previous_purchases =1 Then 'New'
     When previous_purchases Between 2 and 10 Then 'Returning'
     Else 'Loyal'
     End as Customer_segment ,
     Count(*) as Customer_count
     from customer_behaviour_data
     group by Customer_segment;
     
# Q8- What are the three most purchased product within each category
# Step1 - Count each prodct witihn the particular category
With Total_purchase_count As (
Select category, item_purchased , Count(*) As product_count  
from customer_behaviour_data
group by category , item_purchased
),

# Step 2- Lets rank the product within the category
Rank_product As (
Select category,item_purchased , product_count,
Row_Number() Over( 
 Partition by Category 
 Order by product_count Desc 
 ) As rn
 From Total_purchase_count
 )
 
 # Select top 3 product in each category
 
 Select category , item_purchased , product_count
 From Rank_product 
 where rn <= 3 
 order by category, product_count Desc 
 ;

# Q9 - Are customers who are repeat buyers(more than 5 previous purchase )likely to subcribe 
Select subscription_status , count(customer_id) as subscribed_customer
From customer_behaviour_data 
where previous_purchases >5
group by subscription_status;

# Q10- What is the revenue contribution of each age group
Select age_group, Sum(purchase_amount) as revenue_contribution
from customer_behaviour_data
group by age_group 
order by revenue_contribution Desc;

# Q11. How many customers belong to each K-Means customer group?
Select customer_group , Count(*) As Total_Customers
From customer_behaviour_data 
group by customer_group 
Order by customer_group;

# Q12 Which customer group has the highest average purchase amount?
Select customer_group , Round(Avg(purchase_amount),2) As Average_Purchase
From customer_behaviour_data
group by customer_group 
order by Average_Purchase Desc;

# Q13. Which customer group has the highest number of previous purchases?
Select customer_group , Round(Max(previous_purchases),2) As Previous_PurchaseList
From customer_behaviour_data
group by customer_group 
order by Previous_PurchaseList Desc
Limit 1;

# Q 14 What percentage of total revenue comes from each customer group?
WITH GroupRevenue AS
(
    SELECT
        customer_group,
        SUM(purchase_amount) AS Total_Revenue
    FROM customer_behaviour_data
    GROUP BY customer_group
)

SELECT
    customer_group,
    Total_Revenue,
    ROUND(
        Total_Revenue * 100 /
        (SELECT SUM(Total_Revenue) FROM GroupRevenue),
        2
    ) AS Revenue_Percentage
FROM GroupRevenue;

# Q15 – Which customer group has the highest average review rating?
SELECT
    customer_group,
    ROUND(AVG(review_rating), 2) AS Average_Rating
FROM customer_behaviour_data
GROUP BY customer_group
ORDER BY Average_Rating DESC;

# Q16	Which customer group has the highest total number of customers who subscribed?
SELECT
    customer_group,
    COUNT(*) AS Total_Subscribed_Customers
FROM customer_behaviour_data
WHERE subscription_status = 'Yes'
GROUP BY customer_group
ORDER BY Total_Subscribed_Customers DESC;


     